INSERT INTO local_catalog.item_presentation
    (product_id, title, material, description, photo, thumb, categories, edition_order, home_order)
VALUES
    ('loop',
     '{"de":"3D-gedruckter Pflanztopf","en":"3D-printed plant pot","ru":"Горшок, напечатанный на 3D-принтере","pl":"Doniczka z druku 3D","it":"Vaso stampato in 3D","fr":"Pot de fleurs imprimé en 3D","es":"Maceta impresa en 3D"}',
     '{"de":"Kunststoff","en":"Plastic","ru":"Пластик","pl":"Tworzywo sztuczne","it":"Plastica","fr":"Plastique","es":"Plástico"}',
     '{"de":"Loop ist ein runder Pflanztopf mit feinen horizontalen Drucklinien.","en":"Loop is a rounded plant pot with fine horizontal print lines.","ru":"Loop — округлый горшок с тонкими горизонтальными линиями на поверхности.","pl":"Loop to zaokrąglona doniczka z delikatnymi poziomymi liniami druku.","it":"Loop è un vaso arrotondato con sottili linee di stampa orizzontali.","fr":"Loop est un pot arrondi à fines lignes d’impression horizontales.","es":"Loop es una maceta redondeada con finas líneas de impresión horizontales."}',
     NULL, NULL, ARRAY['living', 'gifts', 'decor'], NULL, 0),
    ('halo',
     '{"de":"Tischleuchte","en":"Table lamp","ru":"Настольная лампа","pl":"Lampa stołowa","it":"Lampada da tavolo","fr":"Lampe de table","es":"Lámpara de mesa"}',
     '{"de":"Bernsteinfarbenes Glas","en":"Amber glass","ru":"Янтарное стекло","pl":"Bursztynowe szkło","it":"Vetro ambrato","fr":"Verre ambré","es":"Vidrio ámbar"}',
     '{"de":"Die breite Kuppel wirft warmes Licht auf den Tisch. Durch den kurzen Fuß bleibt die Silhouette niedrig.","en":"The broad dome spreads a pool of amber light across the table. A short stem keeps the silhouette low.","ru":"Широкий купол отбрасывает на стол тёплый янтарный свет. Короткая ножка подчёркивает округлую форму абажура.","pl":"Szeroki klosz rozlewa na stole bursztynowe światło. Krótka nóżka podkreśla jego zaokrągloną formę.","it":"La cupola diffonde una luce ambrata sul tavolo. La base bassa mette in risalto il profilo arrotondato.","fr":"Le dôme diffuse une lumière ambrée sur la table. Le pied court souligne la courbe de l’abat-jour.","es":"La pantalla abombada baña la mesa de luz ámbar. El pie corto acentúa su perfil redondeado."}',
     '/shop-edition/halo.webp', '/shop-edition/halo-small.webp', ARRAY['living', 'desk', 'decor'], 0, 1),
    ('arc',
     '{"de":"Skulpturale Creolen","en":"Sculptural hoops","ru":"Серьги-кольца","pl":"Kolczyki koła","it":"Orecchini a cerchio","fr":"Créoles sculpturales","es":"Pendientes de aro"}',
     '{"de":"Polierter Stahl","en":"Polished steel","ru":"Полированная сталь","pl":"Polerowana stal","it":"Acciaio lucido","fr":"Acier poli","es":"Acero pulido"}',
     '{"de":"Zwei Creolen mit rundem Profil. An den geschwungenen Flächen des polierten Stahls spiegelt sich das Licht.","en":"Two sculptural hoops with a rounded profile. The polished steel picks up reflections along the curves.","ru":"Пара скульптурных колец с округлым профилем. Изгибы полированной стали ловят блики при движении.","pl":"Para kolczyków o zaokrąglonym profilu. Polerowana stal odbija światło na wypukłych powierzchniach.","it":"Due cerchi scultorei dal profilo arrotondato. L’acciaio lucido cattura i riflessi lungo le curve.","fr":"Deux créoles au profil arrondi. L’acier poli accroche la lumière le long des courbes.","es":"Dos aros escultóricos de perfil redondeado. El acero pulido refleja la luz a lo largo de sus curvas."}',
     '/shop-edition/arc.webp', '/shop-edition/arc-small.webp', ARRAY['carry', 'gifts'], 1, 2),
    ('tide',
     '{"de":"Espressotasse","en":"Espresso cup","ru":"Чашка для эспрессо","pl":"Filiżanka do espresso","it":"Tazzina da espresso","fr":"Tasse à expresso","es":"Taza de espresso"}',
     '{"de":"Kobaltblau glasierte Keramik","en":"Cobalt-glazed ceramic","ru":"Керамика с кобальтовой глазурью","pl":"Ceramika z kobaltowym szkliwem","it":"Ceramica smaltata blu cobalto","fr":"Céramique émaillée bleu cobalt","es":"Cerámica con esmalte cobalto"}',
     '{"de":"Die tiefblaue Glasur glänzt am Rand. Der runde Henkel greift die Form der kleinen Espressotasse auf.","en":"Deep blue glaze catches the light along the rim. A rounded handle echoes the shape of the little espresso cup.","ru":"Глубокая синяя глазурь блестит по краю. Небольшая округлая ручка повторяет очертания чашки.","pl":"Kobaltowe szkliwo łapie światło na krawędzi. Zaokrąglone uszko powtarza kształt niewielkiej filiżanki.","it":"Lo smalto blu intenso riflette la luce sul bordo. Il manico arrotondato riprende la curva della tazzina.","fr":"L’émail bleu profond accroche la lumière sur le bord. L’anse arrondie reprend la courbe de la petite tasse.","es":"El esmalte azul intenso refleja la luz en el borde. El asa redondeada sigue la curva de la tacita."}',
     NULL, NULL, ARRAY['living', 'kitchen', 'gifts'], 2, 3),
    ('folio',
     '{"de":"Notizbuch","en":"Clothbound notebook","ru":"Блокнот","pl":"Notes w płótnie","it":"Taccuino in tela","fr":"Carnet toilé","es":"Cuaderno de tela"}',
     '{"de":"Waldgrünes Leinen","en":"Forest-green linen","ru":"Тёмно-зелёный лён","pl":"Ciemnozielony len","it":"Lino verde bosco","fr":"Lin vert forêt","es":"Lino verde bosque"}',
     '{"de":"Der waldgrüne Leineneinband reicht über den Buchrücken. Das feine Gewebe hebt sich vom hellen Buchschnitt ab.","en":"A forest-green linen cover wraps around the spine. The fine weave contrasts with the pale edges of the pages.","ru":"Обложка и корешок обтянуты тёмно-зелёным льном. На его фоне хорошо виден светлый срез страниц.","pl":"Okładkę i grzbiet pokrywa ciemnozielony len. Drobny splot kontrastuje z jasnymi krawędziami stron.","it":"Il lino verde bosco avvolge la copertina e il dorso. La trama fine contrasta con il taglio chiaro delle pagine.","fr":"Le lin vert forêt enveloppe la couverture et le dos. Sa trame fine contraste avec la tranche claire des pages.","es":"El lino verde bosque envuelve la cubierta y el lomo. Su trama fina contrasta con el canto claro de las hojas."}',
     '/shop-edition/folio.webp', '/shop-edition/folio-small.webp', ARRAY['desk', 'gifts'], 3, 4),
    ('dune',
     '{"de":"Leinenkissen","en":"Linen cushion","ru":"Льняная подушка","pl":"Poduszka lniana","it":"Cuscino in lino","fr":"Coussin en lin","es":"Cojín de lino"}',
     '{"de":"Terrakottafarbenes Leinen","en":"Terracotta linen","ru":"Терракотовый лён","pl":"Len w kolorze terakoty","it":"Lino terracotta","fr":"Lin terre cuite","es":"Lino color terracota"}',
     '{"de":"Das leicht unregelmäßige Gewebe fängt das Licht in den Falten des Kissens ein.","en":"The slightly uneven weave catches the light across the folds of the cushion.","ru":"На складках подушки особенно хорошо заметно неровное плетение льна.","pl":"Lekko nieregularny splot widać szczególnie dobrze na fałdach poduszki.","it":"La trama leggermente irregolare risalta nelle pieghe del cuscino.","fr":"La trame légèrement irrégulière se révèle dans les plis du coussin.","es":"La trama ligeramente irregular resalta en los pliegues del cojín."}',
     '/shop-edition/dune.webp', '/shop-edition/dune-small.webp', ARRAY['living', 'decor'], 4, 5),
    ('iris',
     '{"de":"Sonnenbrille","en":"Sunglasses","ru":"Солнцезащитные очки","pl":"Okulary przeciwsłoneczne","it":"Occhiali da sole","fr":"Lunettes de soleil","es":"Gafas de sol"}',
     '{"de":"Durchscheinendes blaues Acetat","en":"Translucent blue acetate","ru":"Полупрозрачный синий ацетат","pl":"Półprzezroczysty niebieski octan","it":"Acetato blu traslucido","fr":"Acétate bleu translucide","es":"Acetato azul translúcido"}',
     '{"de":"An den blauen Rändern um die dunklen Gläser scheint Licht durch die Fassung.","en":"Light passes through the blue edges of the frame around the darker lenses.","ru":"Вокруг тёмных линз синяя оправа просвечивает на свету.","pl":"Niebieskie brzegi oprawek przepuszczają światło wokół ciemnych soczewek.","it":"La luce attraversa i bordi blu della montatura intorno alle lenti scure.","fr":"La lumière traverse les bords bleus de la monture autour des verres foncés.","es":"La luz atraviesa el borde azul de la montura alrededor de las lentes oscuras."}',
     '/shop-edition/iris.webp', '/shop-edition/iris-small.webp', ARRAY['carry'], 5, 6),
    ('kestrel',
     '{"de":"Gebogene Buchstützen","en":"Curved bookends","ru":"Держатели для книг","pl":"Podpórki do książek","it":"Fermalibri curvi","fr":"Serre-livres courbes","es":"Sujetalibros curvos"}',
     '{"de":"Gebogenes Walnussholz","en":"Bent walnut","ru":"Гнутая древесина ореха","pl":"Gięte drewno orzechowe","it":"Noce curvato","fr":"Noyer cintré","es":"Madera de nogal curvada"}',
     '{"de":"Zwei gebogene Holzstützen halten die Bücherreihe an beiden Enden zusammen.","en":"Two bent wooden supports frame the ends of a row of books.","ru":"Две изогнутые опоры поддерживают ряд книг с обеих сторон.","pl":"Dwie wygięte podpórki podtrzymują rząd książek z obu stron.","it":"Due sostegni in legno curvato racchiudono la fila di libri.","fr":"Deux supports en bois cintré encadrent une rangée de livres.","es":"Dos apoyos de madera curvada enmarcan los extremos de una fila de libros."}',
     '/shop-edition/kestrel.webp', '/shop-edition/kestrel-small.webp', ARRAY['living', 'desk', 'decor'], 6, 7),
    ('moss',
     '{"de":"Steinzeugkaraffe","en":"Stoneware carafe","ru":"Керамический графин","pl":"Karafka kamionkowa","it":"Caraffa in gres","fr":"Carafe en grès","es":"Jarra de gres"}',
     '{"de":"Salbeigrüne Sprenkelglasur","en":"Speckled sage glaze","ru":"Шалфейная глазурь в крапинку","pl":"Szałwiowe szkliwo w kropki","it":"Smalto salvia puntinato","fr":"Émail sauge moucheté","es":"Esmalte verde salvia moteado"}',
     '{"de":"Feine Sprenkel durchziehen die salbeigrüne Glasur der Karaffe.","en":"Small speckles break up the soft sage green of the glaze.","ru":"Мелкие крапинки проступают сквозь приглушённый зелёный тон глазури.","pl":"Drobne plamki urozmaicają szałwiową zieleń szkliwa.","it":"Piccole macchie punteggiano il verde tenue dello smalto.","fr":"De fines mouchetures ponctuent le vert tendre de l’émail.","es":"Pequeñas motas salpican el verde suave del esmalte."}',
     '/shop-edition/moss.webp', '/shop-edition/moss-small.webp', ARRAY['living', 'kitchen'], 7, 8),
    ('fold',
     '{"de":"Kartenetui","en":"Cardholder","ru":"Картхолдер","pl":"Etui na karty","it":"Portacarte","fr":"Porte-cartes","es":"Tarjetero"}',
     '{"de":"Sattelleder","en":"Saddle leather","ru":"Шорно-седельная кожа","pl":"Skóra rymarska","it":"Cuoio da selleria","fr":"Cuir de sellerie","es":"Cuero de guarnicionería"}',
     '{"de":"Gefaltetes braunes Leder bildet ein flaches Fach für Karten. Naht und offene Lederkante zeichnen die Form nach.","en":"Folded brown leather forms a slim pocket for cards. The exposed edge and stitching follow the outline of the fold.","ru":"Сложенная коричневая кожа образует тонкий карман для карт. Строчка и открытый срез подчёркивают линию сгиба.","pl":"Złożona brązowa skóra tworzy płaską kieszonkę na karty. Szew i widoczna krawędź podkreślają linię zgięcia.","it":"Il cuoio marrone si piega a formare una tasca sottile per le carte. Il bordo a vista e la cucitura seguono la piega.","fr":"Le cuir brun se replie pour former une fine poche à cartes. La couture et la tranche apparente soulignent le pli.","es":"El cuero marrón se pliega en un bolsillo fino para tarjetas. La costura y el canto visto siguen la línea del pliegue."}',
     '/shop-edition/fold.webp', '/shop-edition/fold-small.webp', ARRAY['carry'], 8, 9),
    ('prism',
     '{"de":"Kerzenhalter","en":"Glass candlestick","ru":"Стеклянный подсвечник","pl":"Świecznik szklany","it":"Candeliere in vetro","fr":"Bougeoir en verre","es":"Candelero de vidrio"}',
     '{"de":"Rauchviolettes Glas","en":"Smoky violet glass","ru":"Дымчато-фиолетовое стекло","pl":"Dymnofioletowe szkło","it":"Vetro viola fumé","fr":"Verre violet fumé","es":"Vidrio violeta ahumado"}',
     '{"de":"An den dickeren Stellen des Halters erscheint das violette Glas dunkler.","en":"The purple glass darkens where the walls of the candleholder thicken.","ru":"В толстых участках стекла фиолетовый оттенок выглядит глубже.","pl":"Fiolet szkła ciemnieje tam, gdzie ścianki świecznika są grubsze.","it":"Il vetro viola si scurisce nei punti in cui le pareti sono più spesse.","fr":"Le violet s’intensifie là où le verre du bougeoir s’épaissit.","es":"El vidrio violeta se oscurece donde las paredes son más gruesas."}',
     '/shop-edition/prism.webp', '/shop-edition/prism-small.webp', ARRAY['living', 'decor'], 9, 10),
    ('loom',
     '{"de":"Rollmäppchen","en":"Roll-up pencil case","ru":"Пенал-скрутка","pl":"Zwijany piórnik","it":"Astuccio arrotolabile","fr":"Trousse à rouler","es":"Estuche enrollable"}',
     '{"de":"Marineblaues Segeltuch","en":"Navy canvas","ru":"Тёмно-синяя парусина","pl":"Granatowe płótno","it":"Tela blu navy","fr":"Toile bleu marine","es":"Lona azul marino"}',
     '{"de":"Ausgerollt liegt das Mäppchen flach und die Stifte sind nebeneinander zu sehen.","en":"The canvas opens flat so the pens and pencils can lie side by side.","ru":"В развёрнутом пенале ручки и карандаши лежат в ряд.","pl":"Rozłożony piórnik leży płasko, a przybory układają się obok siebie.","it":"Una volta srotolato, l’astuccio dispone le matite una accanto all’altra.","fr":"Une fois déroulée, la trousse présente les crayons côte à côte.","es":"Al desenrollar la lona, los lápices quedan uno al lado del otro."}',
     '/shop-edition/loom.webp', '/shop-edition/loom-small.webp', ARRAY['carry', 'desk'], 10, 11),
    ('rook',
     '{"de":"Pfeffermühle","en":"Pepper mill","ru":"Мельница для перца","pl":"Młynek do pieprzu","it":"Macinapepe","fr":"Moulin à poivre","es":"Molinillo de pimienta"}',
     '{"de":"Geschwärzte Eiche","en":"Blackened oak","ru":"Чернёный дуб","pl":"Czerniony dąb","it":"Rovere annerito","fr":"Chêne noirci","es":"Roble ennegrecido"}',
     '{"de":"Unter der dunklen Oberfläche bleibt die Maserung des Mühlenkörpers sichtbar.","en":"The dark finish leaves the oak grain visible along the mill’s body.","ru":"Под тёмной отделкой корпуса мельницы просматривается рисунок дуба.","pl":"Spod ciemnego wykończenia korpusu widać rysunek dębu.","it":"La finitura scura lascia intravedere le venature del legno sul corpo del macinapepe.","fr":"Sous la finition sombre, les veines du chêne restent visibles.","es":"El acabado oscuro deja ver la veta del roble en el cuerpo del molinillo."}',
     '/shop-edition/rook.webp', '/shop-edition/rook-small.webp', ARRAY['living', 'kitchen'], 11, 12),
    ('cove',
     '{"de":"Leinenbeutel","en":"Linen tote","ru":"Сумка-шопер","pl":"Torba na ramię","it":"Borsa in tela","fr":"Cabas en lin","es":"Bolsa de tela"}',
     '{"de":"Sandfarbenes Leinen","en":"Sand-coloured linen","ru":"Лён песочного цвета","pl":"Len w kolorze piasku","it":"Lino color sabbia","fr":"Lin sable","es":"Lino color arena"}',
     '{"de":"Zwei lange Henkel laufen in den weichen Stoff der offenen Tasche über.","en":"Long handles and a simple open top follow the soft folds of the fabric.","ru":"Длинные ручки и открытый верх подчёркивают мягкие складки сумки.","pl":"Długie uchwyty i otwarta góra podkreślają miękkie fałdy tkaniny.","it":"Due manici lunghi accompagnano le pieghe morbide della borsa aperta.","fr":"Deux longues anses prolongent les plis souples de ce cabas ouvert.","es":"Las asas largas y la boca abierta acompañan los pliegues de la tela."}',
     '/shop-edition/cove.webp', '/shop-edition/cove-small.webp', ARRAY['carry'], 12, 13),
    ('flute',
     '{"de":"Rillenvase","en":"Ribbed vase","ru":"Рифлёная ваза","pl":"Wazon ryflowany","it":"Vaso scanalato","fr":"Vase cannelé","es":"Jarrón estriado"}',
     '{"de":"Klarglas","en":"Clear glass","ru":"Прозрачное стекло","pl":"Przezroczyste szkło","it":"Vetro trasparente","fr":"Verre transparent","es":"Vidrio transparente"}',
     '{"de":"Senkrechte Rillen ziehen die Spiegelungen an den klaren Wänden in die Länge.","en":"Vertical ribs stretch and break up reflections along the clear sides.","ru":"Вертикальные рёбра вытягивают и преломляют отражения на прозрачных стенках.","pl":"Pionowe żłobienia wydłużają i załamują odbicia na przezroczystych ściankach.","it":"Le scanalature verticali allungano e spezzano i riflessi sul vetro.","fr":"Les cannelures verticales étirent et dédoublent les reflets sur le verre.","es":"Las estrías verticales alargan y fragmentan los reflejos en el vidrio."}',
     '/shop-edition/flute.webp', '/shop-edition/flute-small.webp', ARRAY['living', 'decor'], 13, 14),
    ('dot',
     '{"de":"Briefablage","en":"Letter tray","ru":"Лоток для бумаг","pl":"Tacka na dokumenty","it":"Vaschetta portadocumenti","fr":"Corbeille à courrier","es":"Bandeja para documentos"}',
     '{"de":"Kirschrotes Metall","en":"Cherry-red metal","ru":"Вишнёво-красный металл","pl":"Wiśniowy metal","it":"Metallo rosso ciliegia","fr":"Métal rouge cerise","es":"Metal rojo cereza"}',
     '{"de":"Die niedrigen Seiten halten die leuchtend rote Ablage dicht an der Tischplatte.","en":"Low sides keep the profile of the bright red tray close to the desk.","ru":"Невысокие бортики делают ярко-красный лоток почти плоским.","pl":"Niskie boki nadają czerwonej tacce płaski profil na biurku.","it":"I bordi bassi mantengono il profilo del vassoio rosso vicino al piano della scrivania.","fr":"Les rebords bas donnent à la corbeille rouge une silhouette proche du bureau.","es":"Los bordes bajos mantienen el perfil de la bandeja roja cerca de la mesa."}',
     '/shop-edition/dot.webp', '/shop-edition/dot-small.webp', ARRAY['desk'], 14, 15),
    ('tempo',
