INSERT INTO local_catalog.recommendation (product_id, section, item_id, position)
SELECT r.product_id, r.section, item.id, item.seq::integer - 1
FROM (VALUES
    ('loop', 'studio',  ARRAY['loop-mini','loop-wide','loop-tray','loop-tall','loop-duo','loop-stand']),
    ('loop', 'related', ARRAY['loop-mini','loop-wide','loop-tray','loop-tall','loop-duo','loop-stand']),
    ('tide', 'studio',  ARRAY['halo','flute','reed','prism','drift','bend']),
    ('tide', 'related', ARRAY['moss','hex','stripe','rook','wave'])
) AS r(product_id, section, ids)
CROSS JOIN LATERAL unnest(r.ids) WITH ORDINALITY AS item(id, seq);

-- The original edition detail pages showed the next four designs in sequence,
-- wrapping around the end. Materialise those initial choices so a curator
-- can change one rail without reordering unrelated pages.
INSERT INTO local_catalog.recommendation (product_id, section, item_id, position)
SELECT source.product_id, 'related', target.product_id, target.seq::integer - 1
FROM local_catalog.item_presentation AS source
JOIN local_catalog.product AS p ON p.id = source.product_id AND p.kind = 'edition'
CROSS JOIN LATERAL (
    SELECT candidate.product_id, row_number() OVER (
        ORDER BY (candidate.edition_order < source.edition_order), candidate.edition_order
    ) AS seq
    FROM local_catalog.item_presentation AS candidate
    WHERE candidate.edition_order IS NOT NULL AND candidate.product_id <> source.product_id
    ORDER BY seq
    LIMIT 4
) AS target;
